// Approved painted series samples. Embedded for identical references across clients.
const references: Record<string, readonly string[]> = {
  "protagonist-3": ["", "", ""],
  "protagonist-4": ["", "", ""],
  "protagonist-6": [""],
};

export function canonicalPaintedStyleReferences(styleId: string | undefined): Blob[] {
  const encoded = styleId ? references[styleId] : undefined;
  return (encoded ?? []).map(sample => new Blob([Uint8Array.from(atob(sample), value => value.charCodeAt(0))], { type: 'image/jpeg' }));
}
